<div class="page-actions justify-content-end"><button class="btn btn-primary" id="newGoal"><i class="bi bi-plus-lg me-2"></i>New savings goal</button></div>
<div class="row g-3" id="goalCards"></div>
<div class="modal fade" id="goalModal"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" id="goalForm"><div class="modal-header"><h5 class="modal-title">New savings goal</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="id"><div class="mb-3"><label class="form-label">Goal title</label><input class="form-control" name="title" required></div><div class="mb-3 goal-account-field"><label class="form-label">Savings account</label><select class="form-select" name="account_id" required></select></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Target amount</label><input class="form-control" name="target_amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-6"><label class="form-label">Target date</label><input class="form-control" name="target_date" type="date"></div></div><div id="goalRateNotice"></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Create goal</button></div></form></div></div>
<div class="modal fade" id="goalMoveModal"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" id="goalMoveForm"><div class="modal-header"><h5 class="modal-title">Update savings</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="goal_id"><input type="hidden" name="mode"><div class="mb-3"><label class="form-label" id="goalAccountLabel">From account</label><select class="form-select" name="money_account_id" required></select></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Amount</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-6"><label class="form-label">Date</label><input class="form-control" name="transaction_date" type="date" value="{{ now()->toDateString() }}" required></div></div><div id="goalMoveRateNotice"></div><div class="mt-3"><label class="form-label">Description</label><input class="form-control" name="description"></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save</button></div></form></div></div>
@endsection
@push('scripts')
<script>
(()=>{const M=MyLedger,cards=document.querySelector('#goalCards'),form=document.querySelector('#goalForm'),move=document.querySelector('#goalMoveForm');let goals=[],accounts=[];
function updateGoalRateNotices(){
    const acc1=accounts.find(a=>String(a.id)===String(form.account_id.value));
    M.renderCurrencyRateNotice(document.querySelector('#goalRateNotice'),form.target_amount.value,acc1?.currency_id);
    const acc2=accounts.find(a=>String(a.id)===String(move.money_account_id.value));
    M.renderCurrencyRateNotice(document.querySelector('#goalMoveRateNotice'),move.amount.value,acc2?.currency_id);
}
async function refs(){[accounts]=await Promise.all([M.request('/ajax/accounts'),M.getCurrencies()]);M.fillSelect(form.account_id,accounts.filter(a=>M.typeValue(a.type)==='savings'),{placeholder:'Select savings account'});M.fillSelect(move.money_account_id,accounts,{placeholder:'Select account'});updateGoalRateNotices();}
form.account_id.onchange=updateGoalRateNotices; form.target_amount.oninput=updateGoalRateNotices;
move.money_account_id.onchange=updateGoalRateNotices; move.amount.oninput=updateGoalRateNotices;async function load(){try{goals=await M.request('/ajax/savings-goals');cards.innerHTML=goals.length?goals.map(g=>`<div class="col-md-6 col-xl-4"><div class="surface-card goal-card h-100"><div class="goal-top"><div><span class="badge-soft">${g.is_completed?'Completed':'In progress'}</span><h3 class="h6 fw-bold mt-3 mb-1">${M.esc(g.title)}</h3><div class="small text-secondary">${M.esc(g.account?.name||'')} · Target ${M.date(g.target_date)}</div></div><div class="goal-progress">${Math.round(g.progress_percent)}%</div></div><div class="progress-thin mt-4"><div class="progress-bar" style="height:100%;width:${Math.min(100,g.progress_percent)}%"></div></div><div class="d-flex justify-content-between small mt-2"><span>${M.money(g.allocated_amount, g.currency.symbol)} saved</span><span class="text-secondary">${M.money(g.target_amount, g.currency.symbol)} goal</span></div><div class="d-flex gap-2 mt-4"><button class="btn btn-sm btn-outline-secondary edit-goal" data-id="${g.id}"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-primary flex-fill contribute" data-id="${g.id}">Contribute</button><button class="btn btn-sm btn-outline-secondary flex-fill withdraw" data-id="${g.id}">Withdraw</button></div></div></div>`).join(''):'<div class="col-12"><div class="surface-card empty-state"><i class="bi bi-piggy-bank"></i>No savings goals yet.</div></div>';}catch(e){M.toast(e.message,'danger')}}document.querySelector('#newGoal').onclick=()=>refs().then(()=>{form.reset();form.id.value='';document.querySelector('.goal-account-field').classList.remove('d-none');form.account_id.disabled=false;form.querySelector('.modal-title').textContent='New savings goal';M.modal('goalModal')});cards.onclick=e=>{const edit=e.target.closest('.edit-goal'),c=e.target.closest('.contribute'),w=e.target.closest('.withdraw');if(edit){const g=goals.find(x=>String(x.id)===edit.dataset.id);form.reset();form.id.value=g.id;form.title.value=g.title;form.target_amount.value=g.target_amount;form.target_date.value=g.target_date?String(g.target_date).slice(0,10):'';document.querySelector('.goal-account-field').classList.add('d-none');form.account_id.disabled=true;form.querySelector('.modal-title').textContent='Edit savings goal';M.modal('goalModal');return;}const b=c||w;if(!b)return;move.reset();move.goal_id.value=b.dataset.id;move.mode.value=c?'contribute':'withdraw';move.transaction_date.value='{{ now()->toDateString() }}';document.querySelector('#goalAccountLabel').textContent=c?'From account':'To account';refs().then(()=>M.modal('goalMoveModal'))};form.onsubmit=async e=>{e.preventDefault();const d=M.payload(form),id=d.id;delete d.id;if(id)delete d.account_id;try{await M.request(id?'/ajax/savings-goals/'+id:'/ajax/savings-goals',{method:id?'PATCH':'POST',body:JSON.stringify(d)});M.modal('goalModal','hide');M.toast(id?'Savings goal updated.':'Savings goal created.');load()}catch(err){M.errors(form,err)}};move.onsubmit=async e=>{e.preventDefault();const d=M.payload(move),id=d.goal_id,mode=d.mode,account=d.money_account_id;delete d.goal_id;delete d.mode;delete d.money_account_id;if(mode==='contribute')d.source_account_id=account;else d.destination_account_id=account;try{await M.request(`/ajax/savings-goals/${id}/${mode}`,{method:'POST',body:JSON.stringify(d)});M.modal('goalMoveModal','hide');M.toast(mode==='contribute'?'Savings contribution recorded.':'Savings withdrawal recorded.');load()}catch(err){M.errors(move,err)}};Promise.all([refs(),load()])})();
</script>
@endpush
